// span-waveform — a live audio waveform running across a row of keys. Each key keeps
// its own glass; the wave is one continuous line behind the bezels (gap pixels are
// hidden), scrolling right → left with the newest sound at the right edge.
//
// ctx.data.audio (optional): { levels: number[] } — recent peak levels 0–1, oldest
// first, from an audio source (src/audio/). Without it the facet synthesizes music.

import { surface, keyInto, path, linearGradient, url, circle, n, P } from '../../scene/index.js';
import { noise1 } from '../../scene/noise.js';

/** Synthetic music envelope at time x: beat-driven kick + phrase swell + texture. */
function synth(x, seed) {
  const beat = x * 2; // 120 BPM
  const kick = Math.exp(-((beat % 1) * 5));
  const phrase = 0.55 + 0.45 * Math.sin(x * 0.4 + noise1(x * 0.1, seed) * 3);
  const tex = noise1(x * 7, seed + 11);
  return Math.min(1, (0.18 + 0.5 * kick * phrase + 0.32 * tex * phrase));
}

export default {
  id: 'span-waveform',
  title: 'Waveform',
  category: 'Waveforms & Audio',
  description: 'A live audio waveform running across a whole row of keys — one continuous line behind the bezels, newest sound at the right.',
  tags: ['audio', 'waveform', 'music', 'live', 'span', 'oscilloscope'],
  surface: 'span',
  span: { cols: 'all', rows: 1 },
  data: ['audio'],
  fps: 15,
  loop: 8,
  params: {
    speed: { type: 'number', default: 1, min: 0.25, max: 3, step: 0.05, label: 'Scroll speed' },
  },
  order: 10,
  render(ctx) {
    const d = surface(ctx);
    const { w, h, t, grid } = ctx;
    d.add(`<rect width="${n(w)}" height="${n(h)}" fill="#000000"/>`);
    // every key keeps its own material
    for (const cell of grid.cells) keyInto(d, cell, (k) => { k.background({ tone: 'active' }); }, { tag: `k${cell.i}`, clip: false });
    const levels = ctx.data.audio?.levels;
    const cols = Math.max(24, Math.round(w / 3));
    const seconds = 4 / ctx.params.speed;                 // the strip shows the last 4 s at speed 1
    const mid = h / 2, amp = grid.key.h * 0.38;
    let top = '', bot = '';
    for (let i = 0; i <= cols; i++) {
      const x = (i / cols) * w;
      const age = (1 - i / cols) * seconds;
      const v = levels?.length ? levels[Math.max(0, Math.min(levels.length - 1, Math.round((i / cols) * (levels.length - 1))))] : synth(t - age, ctx.seed);
      const a = Math.max(0.03, v) * amp;
      top += `${i ? 'L' : 'M'}${n(x)} ${n(mid - a)}`;
      bot = `L${n(x)} ${n(mid + a * 0.82)}${bot}`;
    }
    const gid = d.id('wave');
    const hue = ctx.hue;
    d.def(linearGradient(gid, [[0, ctx.theme.spectral(hue + 60), 0.25], [0.5, ctx.theme.spectral(hue), 0.85], [1, ctx.theme.spectral(hue - 70), 1]], { x1: 0, y1: 0, x2: w, y2: 0, gradientUnits: 'userSpaceOnUse' }));
    d.add(path(`${top}${bot}Z`, { fill: url(gid), fillOpacity: d.dark ? 0.85 : 0.7 }));
    // the center Beam and the live head
    d.add(path(P().M(0, mid).L(w, mid).d, { stroke: d.colors.beam || '#ffffff', strokeWidth: d.m.hair, strokeOpacity: 0.35 }));
    d.add(circle({ cx: w - d.m.safe, cy: mid, r: d.m.bold, fill: d.dark ? '#ffffff' : d.tone('active') }));
    return d.svg();
  },
};

sources.prism-deck/src/facets/themes/_d5-deck.js:
// D5's theme previews: the architect's whole-device preview (./_deck.js) with one change — on the
// Galleon 100 SD the screen shows the real everyday dashboard (screen-galleon-dashboard) dressed in
// the theme, instead of a placeholder clock. Everything else (keys, strip, Neo bar) is themeFacet's.

import { themeFacet } from './_deck.js';
import { normalizeFacet } from '../schema.js';
import { createContext } from '../../scene/context.js';
import { svgInner, n } from '../../scene/svg.js';
import dashboardModule from '../screens/galleon-dashboard.js';

const dashboard = normalizeFacet(dashboardModule, 'screens/galleon-dashboard.js');

export function themeFacetWithScreen(themeId, opts) {
  const base = themeFacet(themeId, opts);
  return {
    ...base,
    render(ctx) {
      const S = ctx.deck?.screen;
      if (!S || S.kind !== 'galleon') return base.render(ctx);
      const svg = base.render({ ...ctx, deck: { ...ctx.deck, screen: null } });
      const sc = createContext(dashboard, { theme: themeId, mode: ctx.theme.mode, t: ctx.t, now: ctx.now, seed: ctx.seed, data: ctx.data, reduced: ctx.reduced, idPrefix: `${ctx.idPrefix}gs`, tzOffset: ctx.clock?.tzOffset ?? 0 });
      // hoist the dashboard's defs into the document's top-level <defs>, so per-slice culling can
      // bound the screen by its widget clips and the key slices never carry the screen's markup
      let defs = '', body = svgInner(dashboard.render(sc));
      if (body.startsWith('<defs>')) { const e = body.indexOf('</defs>'); defs = body.slice(6, e); body = body.slice(e + 7); }
      const open = svg.indexOf('>', svg.indexOf('<svg')) + 1, end = svg.lastIndexOf('</svg>');
      const g = `<g transform="translate(${n(S.x)} ${n(S.y)})">${body}</g>`;
      const head = !defs ? svg.slice(0, end) : svg.startsWith('<defs>', open) ? `${svg.slice(0, open + 6)}${defs}${svg.slice(open + 6, end)}` : `${svg.slice(0, open)}<defs>${defs}</defs>${svg.slice(open, end)}`;
      return head + g + svg.slice(end);
    },
  };
}

sources.prism-deck/src/facets/themes/_deck.js:
// Themes gallery helper: a whole-device preview of one theme — every key a real
// glyph + label + state, plus the strip / screen where the device has them.
//
//   // src/facets/themes/paper.js
//   import { themeFacet } from './_deck.js';
//   export default themeFacet('paper', { category: 'Light', title: 'Paper', description: '…' });

import { surface, compose, keyInto, svgInner, n } from '../../scene/index.js';
import { createContext } from '../../scene/context.js';
import { normalizeFacet } from '../schema.js';
import dashboardModule from '../screens/galleon-dashboard.js';
import { glyphRegistry } from '../../glyphs/_registry.js';
import { arc } from '../../scene/shapes.js';
import { splitElements } from '../../scene/cull.js';
import { lerp } from '../../scene/easing.js';

/** The default key layout: glyph, state, label — cycled across however many keys a device has. */
export const SHOWCASE = [
  ['mic', 'on', 'Mic'], ['volume', 'on', 'Volume'], ['play-pause', 'playing', 'Play'], ['broadcast', 'live', 'On Air'],
  ['cpu', 'busy', 'CPU'], ['clock', 'default', 'Clock'], ['bulb', 'on', 'Lights'], ['power', 'on', 'Power'],
  ['mic', 'off', 'Muted'], ['volume', 'muted', 'Silent'], ['play-pause', 'paused', 'Paused'], ['broadcast', 'offline', 'Offline'],
  ['bulb', 'off', 'Lamp'], ['power', 'off', 'Standby'], ['cpu', 'idle', 'Idle'], ['clock', 'default', 'Timer'],
];

/** Draw a key cell with a glyph in the theme. */
export function showcaseKey(k, [glyph, state, label], { hue } = {}) {
  const reg = glyphRegistry().glyphs;
  const g = reg.get(glyph) || reg.values().next().value;
  if (!g) return;
  const st = g.states[state] ? state : g.defaultState;
  k.background({ tone: g.states[st] });
  k.glyph(g.id, { state: st, labeled: true });
  k.label(label, { color: g.states[st] === 'off' ? 'dim' : undefined });
  void hue;
}

const DASHBOARD = normalizeFacet(dashboardModule, 'screens/galleon-dashboard.js');

/**
 * The Galleon screen in a preview: the real everyday dashboard (screen-galleon-dashboard)
 * rendered in this theme (D5's approach). Its defs are hoisted into the document's <defs>
 * so per-slice culling bounds the screen by its widget clips and key slices never carry it.
 */
function screenInto(d, ctx, S) {
  const sc = createContext(DASHBOARD, { theme: ctx.facet.theme || ctx.theme.id, mode: ctx.theme.mode, t: ctx.t, now: ctx.now, seed: ctx.seed, data: ctx.data, reduced: ctx.reduced, idPrefix: `${ctx.idPrefix}gs`, tzOffset: ctx.clock?.tzOffset ?? 0 });
  let body = svgInner(DASHBOARD.render(sc));
  if (body.startsWith('<defs>')) { const e = body.indexOf('</defs>'); d.def(body.slice(6, e)); body = body.slice(e + 7); }
  const sx = S.w / sc.w, sy = S.h / sc.h;
  // top-level elements stay top-level (each widget its own), so per-slice culling gives every Galleon
  // widget window only its own widget (API 1.5.1: deck renders return widget slices)
  const tf = S.x || S.y || sx !== 1 || sy !== 1 ? `translate(${n(S.x)} ${n(S.y)})${sx !== 1 || sy !== 1 ? ` scale(${n(sx, 4)} ${n(sy, 4)})` : ''}` : null;
  for (const el of splitElements(body)) d.add(tf ? `<g transform="${tf}">${el}</g>` : el);
}

/** A small dial readout for strip segments in previews. */
function dialSegment(p, value, label, i) {
  p.background({ tone: i === 0 ? 'active' : 'idle' });
  p.eyebrow(label);
  p.value(`${Math.round(value * 100)}`, { cy: p.h * 0.48 });
  p.add(arc({ cx: p.w / 2, cy: p.h * 0.5, r: p.h * 0.36, from: -135, to: lerp(-135, 135, value), color: p.tone('active'), width: p.m.line * 1.4 }));
}

export function themeFacet(themeId, { title, description, category = 'Signature', tags = [], order = 10, keys = SHOWCASE } = {}) {
  return {
    id: `theme-${themeId}`,
    title: title || themeId,
    category,
    description: description || `The ${themeId} theme across a whole device: every key, the strip and the screen.`,
    tags: ['theme', 'preview', ...tags],
    surface: 'deck',
    theme: themeId,
    animated: true,
    fps: 8,
    loop: 6,
    order,
    render(ctx) {
      const d = surface(ctx);
      d.add(`<rect width="${ctx.w}" height="${ctx.h}" fill="#000000"/>`);
      ctx.deck.keys.forEach((cell, i) => { const spec = keys[i % keys.length]; const g = glyphRegistry().glyphs.get(spec[0]); keyInto(d, cell, (k) => showcaseKey(k, spec), { tag: `k${i}`, hue: g?.hue }); });
      if (ctx.deck.strip) {
        const S = ctx.deck.strip, w = S.w / S.segments;
        const labels = ['Master', 'Mic', 'Music', 'Chat', 'FX', 'Out'];
        for (let i = 0; i < S.segments; i++) compose(d, { x: S.x + i * w, y: S.y, w, h: S.h }, (p) => dialSegment(p, ctx.values[i] ?? 0.5, labels[i], i), { kind: 'strip', tag: `s${i}` });
      }
      if (ctx.deck.screen && ctx.deck.screen.kind === 'galleon') screenInto(d, ctx, ctx.deck.screen);
      if (ctx.deck.screen && ctx.deck.screen.kind === 'infobar') {
        compose(d, ctx.deck.screen, (p) => {
          p.background({ tone: 'idle' });
          p.value('9:41', { align: 'left', x: 10, cy: p.h * 0.5, size: p.h * 0.5 });
          p.eyebrow(ctx.theme.title, { align: 'right', x: p.w - 10, y: p.h * 0.58, size: p.h * 0.16 });
        }, { kind: 'screen', tag: 'bar' });
      }
      return d.svg();
    },
  };
}

