    const d = arrive(Math.max(0, s.since - 0.12), 0.45, outBack);
    g.dot(24, lerp(10.5, 16, d), 2.3, { opacity: (0.7 + 0.3 * pulse(s.t, 2.4)) * Math.min(1, d * 1.5) });
