// viewers — the audience: a front viewer with a back row that fills in by level
// (1 → 3 people). live: the front viewer lights and breathes, and the back row
// gathers in from the edges.
import { defineGlyph } from '../_glyph.js';
import { arrive, pulse, lerp } from '../../scene/easing.js';

export default defineGlyph({
  id: 'viewers',
  title: 'Viewers',
  category: 'stream',
  tags: ['viewers', 'audience', 'people', 'watching', 'users', 'stream', 'count'],
  states: { offline: 'idle', live: 'active' },
  loop: 2.4,
  draw(g, s) {
    const live = s.state === 'live';
    const k = live ? arrive(s.since, 0.5) : 1;
    const crowd = s.level > 0.66 ? 3 : s.level > 0.33 ? 2 : 1;
    const ox = crowd === 2 ? -3 : 0; // a pair sits off-center so the two read as one group
    // the back row: smaller, higher, dim — a solid head and a shoulder arc that stops short of the front viewer
    const back = (side) => {
      const cx = 24 + side * 12.5 + ox;
      g.group({ x: side * lerp(2.5, 0, k), opacity: k }, () => {
        g.circle(cx, 13.5, 3.75, { role: 'dim', fill: true });
        g.arc(cx, 25, 5.25, side < 0 ? 270 : 315, side < 0 ? 405 : 450, { role: 'dim' });
      });
    };
    if (crowd >= 2) back(1);
    if (crowd >= 3) back(-1);
    // the front viewer
    if (live) g.circle(24 + ox, 21.5, 4.75, { role: 'accent', fill: true, opacity: (0.55 + 0.45 * pulse(s.t, 2.4)) * k });
    g.circle(24 + ox, 21.5, 4.75, { role: 'line' });
    g.path(`M${14.5 + ox} 39A9.5 8.5 0 0 1 ${33.5 + ox} 39`, { role: 'line' });
  },
});

sources.prism-deck/src/glyphs/system/_kit.js:
// Shared drawing kit for the system · status · dev glyphs (Deck Icon Designer I2).
// Pure geometry helpers in 48-unit grid space — no colors, no roles.

import { n } from '../../scene/svg.js';
import { arrive, clamp } from '../../scene/easing.js';

const pt = (p) => `${n(p[0])} ${n(p[1])}`;

/**
 * A quadratic curve p0 → p2 (control q) written as the equivalent cubic 'C' segment. Glyphs avoid
 * 'Q' on purpose: some material themes read quadratic paths as lettering and fill them.
 */
export function quadC(p0, q, p2) {
  const c1 = [p0[0] + (2 / 3) * (q[0] - p0[0]), p0[1] + (2 / 3) * (q[1] - p0[1])];
  const c2 = [p2[0] + (2 / 3) * (q[0] - p2[0]), p2[1] + (2 / 3) * (q[1] - p2[1])];
  return `C${pt(c1)} ${pt(c2)} ${pt(p2)}`;
}
/** Open quadratic curve as path data (M + cubic). */
export const curve = (p0, q, p2) => `M${pt(p0)}${quadC(p0, q, p2)}`;

/** Closed polygon with rounded corners (a quadratic-shaped bend at each vertex) → path data. r: one radius or one per vertex. */
export function roundPoly(pts, r) {
  const N = pts.length;
  const cut = (a, b, rr) => { const dx = b[0] - a[0], dy = b[1] - a[1], L = Math.hypot(dx, dy) || 1, k = Math.min(rr / L, 0.5); return [a[0] + dx * k, a[1] + dy * k]; };
  let d = '';
  for (let i = 0; i < N; i++) {
    const v = pts[i], prev = pts[(i - 1 + N) % N], next = pts[(i + 1) % N];
    const rr = Array.isArray(r) ? r[i] : r;
    const a = cut(v, prev, rr), b = cut(v, next, rr);
    d += `${i ? 'L' : 'M'}${pt(a)}${quadC(a, v, b)}`;
  }
  return `${d}Z`;
}

/** Total length of a polyline. */
export function polyLength(pts) {
  let L = 0;
  for (let i = 1; i < pts.length; i++) L += Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]);
  return L;
}

/** The first fraction k (0–1) of a polyline, by length — for strokes that draw themselves in. */
export function partialPolyline(pts, k) {
  const total = polyLength(pts) * clamp(k);
  const out = [pts[0]];
  let acc = 0;
  for (let i = 1; i < pts.length; i++) {
    const a = pts[i - 1], b = pts[i], L = Math.hypot(b[0] - a[0], b[1] - a[1]);
    if (acc + L >= total) { const f = L ? (total - acc) / L : 0; out.push([a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f]); return out; }
    out.push(b);
    acc += L;
  }
  return out;
}

/** Point at fraction u (0–1, by length) along a polyline. */
export function alongPolyline(pts, u) {
  const p = partialPolyline(pts, u);
  return p[p.length - 1];
}

/** Arrow chevron at the end of an arc (degrees, 0 = up, clockwise): tip slightly past the end, pointing along the sweep. */
export function arcHead(cx, cy, r, deg, { size = 4.5, dir = 1, lead = 1.2 } = {}) {
  const a = (deg * Math.PI) / 180;
  const P = [cx + r * Math.sin(a), cy - r * Math.cos(a)];
  const T = [Math.cos(a) * dir, Math.sin(a) * dir];   // clockwise tangent (× dir)
  const N = [Math.sin(a), -Math.cos(a)];              // outward normal
  const tip = [P[0] + T[0] * lead, P[1] + T[1] * lead];
  const back = [tip[0] - T[0] * size, tip[1] - T[1] * size];
  return [[back[0] + N[0] * size, back[1] + N[1] * size], tip, [back[0] - N[0] * size, back[1] - N[1] * size]];
}

/** The "off" strike shared by wifi / network / cloud: a diagonal that draws itself in over 0.32 s. */
export function strike(g, s, { from = [10.5, 10.5], to = [37.5, 37.5], role = 'accent', weight = 1.1, dur = 0.32 } = {}) {
  const k = arrive(s.since, dur);
  if (k <= 0.001) return;
  g.line(from[0], from[1], from[0] + (to[0] - from[0]) * k, from[1] + (to[1] - from[1]) * k, { role, weight });
}

/** Triangle bump 0 → 1 → 0 over [c - w, c + w] (wrap-aware on a 0–1 circle when wrap = true). */
export function bump(x, c, w, wrap = false) {
  let d = Math.abs(x - c);
  if (wrap) d = Math.min(d, 1 - d);
  return d >= w ? 0 : 1 - d / w;
}

/** Smooth on/off square wave (0–1) for blinks: on for `duty` of the period, edges eased over `soft`. */
export function blink(p, duty = 0.5, soft = 0.08) {
  return p < duty ? Math.min(clamp(p / soft), clamp((duty - p) / soft)) : 0;
}

/** Horizontal extent [x0, x1] of a polygon on the scanline y (null when the line misses it). */
export function rowSpan(poly, y) {
  let lo = Infinity, hi = -Infinity;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const [xi, yi] = poly[i], [xj, yj] = poly[j];
    if ((yi <= y && yj >= y) || (yj <= y && yi >= y)) {
      if (yi === yj) { lo = Math.min(lo, xi, xj); hi = Math.max(hi, xi, xj); continue; }
      const x = xi + ((y - yi) / (yj - yi)) * (xj - xi);
      lo = Math.min(lo, x); hi = Math.max(hi, x);
    }
  }
  return lo === Infinity ? null : [lo, hi];
}

/**
 * A rect [x0, x1] × [y0, y1] with a window cut around a row-convex polygon (plus a margin),
 * returned as up to two closed path strings (left of the window, right of it). Used to seat
 * a symbol inside a fill so it reads in themes that paint every role in one color.
 */
export function rectAround(x0, x1, y0, y1, poly, margin = 1.4, step = 0.5) {
  if (x1 - x0 < 0.05) return [];
  const rows = [];
  for (let y = y0; y <= y1 + 1e-6; y += step) {
    let lo = Infinity, hi = -Infinity;
    for (const dy of [-margin, -margin / 2, 0, margin / 2, margin]) {
      const sp = rowSpan(poly, y + dy);
      if (sp) { lo = Math.min(lo, sp[0] - margin); hi = Math.max(hi, sp[1] + margin); }
    }
    if (lo === Infinity) lo = hi = x1; // the row misses the window: all of it belongs to the left part
    rows.push([Math.min(y, y1), lo, hi]);
  }
  const out = [];
  // left part: x from x0 to min(x1, lo)
  const left = rows.map(([y, lo]) => [y, Math.max(x0, Math.min(x1, lo))]);
  if (left.some(([, x]) => x > x0 + 0.05)) out.push(`M${n(x0)} ${n(y0)}${left.map(([y, x]) => `L${n(x)} ${n(y)}`).join('')}L${n(x0)} ${n(y1)}Z`);
  // right part: x from max(x0, hi) to x1
  const right = rows.map(([y, , hi]) => [y, Math.min(x1, Math.max(x0, hi))]);
  if (right.some(([, x]) => x < x1 - 0.05)) out.push(`M${n(x1)} ${n(y0)}${right.map(([y, x]) => `L${n(x)} ${n(y)}`).join('')}L${n(x1)} ${n(y1)}Z`);
  return out;
}

sources.prism-deck/src/glyphs/system/battery.js:
// battery — a cell with its charge as a fill by level. normal: the charge pours in on
// arrival. charging: a bolt sits in a window cut into the charge (so it reads even where
// a theme paints every role in one color) and a wave of light runs through the charge.
// low: the charge drops to a sliver that blinks.
import { defineGlyph } from '../_glyph.js';
import { arrive, clamp, lerp, pulse, smoothstep } from '../../scene/easing.js';
import { rectAround } from './_kit.js';

const X0 = 10, W = 24, Y0 = 17, H = 14;     // the charge's box inside the cell
// the bolt, row-convex so the window can follow it
const BOLT = [[24.85, 16], [16.3, 25.37], [21.54, 25.37], [19.15, 32], [27.7, 22.63], [22.46, 22.63]];
const LOOP = 1.6;

export default defineGlyph({
  id: 'battery',
  title: 'Battery',
  category: 'system',
  tags: ['battery', 'charge', 'charging', 'power', 'level', 'low'],
  states: { normal: 'active', charging: 'ok', low: 'warn' },
  loop: LOOP,
  draw(g, s) {
    g.rect(6.5, 13.5, 31, 21, { r: 5 });
    g.line(40.5, 20, 40.5, 28, { weight: 1.1 });
    const st = s.state;
    if (st === 'low') {
      const lv = Math.min(clamp(s.level), 0.16);
      const w = Math.max(2.2, W * lv);
      g.rect(X0, Y0, w, H, { r: 1.5, role: 'accent', fill: true, opacity: 0.3 + 0.7 * pulse(s.t, LOOP / 2) }); // blinks twice per loop
      return;
    }
    if (st === 'charging') {
      const lv = clamp(s.level);
      const xe = X0 + W * lv;
      for (const d of rectAround(X0, xe, Y0, Y0 + H, BOLT, 1.4)) g.path(d, { role: 'accent', fill: true, opacity: 0.5 });
      // a wave of light runs through the charge, left → right, once per loop
      const p = s.phase(LOOP);
      const c = lerp(X0 - 4, xe + 4, p), half = 3.5;
      const a = Math.max(X0, c - half), b = Math.min(xe, c + half);
      const fade = smoothstep(0, 0.15, p) * (1 - smoothstep(0.85, 1, p));
      if (b - a > 0.2 && fade > 0.01) for (const d of rectAround(a, b, Y0, Y0 + H, BOLT, 1.4)) g.path(d, { role: 'accent', fill: true, opacity: 0.5 * fade });
      const k = arrive(s.since, 0.36);
      g.polygon(BOLT.map(([x, y]) => [x, y - 2.5 * (1 - k)]), { role: 'fill', join: 'round', opacity: k });
      return;
    }
    // normal: the charge pours in
    const w = W * clamp(s.level) * arrive(s.since, 0.6);
    if (w > 0.3) g.rect(X0, Y0, w, H, { r: Math.min(1.5, w / 2), role: 'accent', fill: true });
  },
});

sources.prism-deck/src/glyphs/system/cpu.js:
// cpu — a chip with pins; while busy its four cores light in turn. The load sets how many
// cores are lit at once (level → 1–4): a lit window of cores chases around the die, the
// lead core brightest, so even a full load keeps moving.
import { defineGlyph } from '../_glyph.js';
import { clamp } from '../../scene/easing.js';

export default defineGlyph({
  id: 'cpu',
  title: 'CPU',
  category: 'system',
  tags: ['cpu', 'processor', 'chip', 'system', 'performance', 'load'],
  states: { busy: 'active', idle: 'idle' },
  loop: 1.2,
  draw(g, s) {
    g.rect(13, 13, 22, 22, { r: 3.5 });
    for (const p of [18.5, 24, 29.5]) {
      g.line(p, 7.5, p, 12, { role: 'dim' });
      g.line(p, 36, p, 40.5, { role: 'dim' });
      g.line(7.5, p, 12, p, { role: 'dim' });
      g.line(36, p, 40.5, p, { role: 'dim' });
    }
    const busy = s.state === 'busy';
    const lead = Math.floor(s.phase(1.2) * 4);
    const count = Math.max(1, Math.ceil(clamp(s.level) * 4 - 1e-9));
    [[18.5, 18.5], [25, 18.5], [25, 25], [18.5, 25]].forEach(([x, y], i) => {
      const rel = (lead - i + 4) % 4;              // 0 = the lead core, then the ones it just left
      const on = busy && rel < count;
      g.rect(x, y, 4.5, 4.5, { r: 1, role: on ? 'spark' : 'fill', fill: true, opacity: on ? (rel === 0 ? 1 : 0.72) : 0.5 });
    });
  },
});

sources.prism-deck/src/glyphs/system/disk.js:
// disk — a drive seen from above: platter, spindle, read arm, activity light. The platter's
// rim is the meter: used space sweeps clockwise from 12 o'clock by level. active: the arm
// seeks across the tracks and the light flickers. idle: the arm parks off the platter.
// full: the meter pins near full and breathes.
import { defineGlyph } from '../_glyph.js';
import { arrive, clamp, lerp, pulse } from '../../scene/easing.js';

const C = [24, 20.5], R = 9;         // platter
const P = [32.5, 34], L = 12;        // arm pivot + length
const LOOP = 2.4;

/** Arm angle (deg, 0 = up, clockwise) that puts the head at distance d from the spindle (on the upper side). */
function armAngle(d) {
  const dist = (a) => { const r = (a * Math.PI) / 180; return Math.hypot(P[0] + L * Math.sin(r) - C[0], P[1] - L * Math.cos(r) - C[1]); };
  const toC = (Math.atan2(C[0] - P[0], P[1] - C[1]) * 180) / Math.PI; // pointing straight at the spindle (closest)
  let lo = toC, hi = toC + 60;
  for (let i = 0; i < 40; i++) { const m = (lo + hi) / 2; if (dist(m) < d) lo = m; else hi = m; }
  return (lo + hi) / 2;
}
const A_IN = armAngle(4.5), A_OUT = armAngle(8), A_PARK = armAngle(11);

export default defineGlyph({
  id: 'disk',
  title: 'Disk',
  category: 'system',
  tags: ['disk', 'drive', 'storage', 'ssd', 'hdd', 'space', 'io'],
  states: { active: 'active', idle: 'idle', full: 'warn' },
  loop: LOOP,
  draw(g, s) {
    const st = s.state;
    g.rect(10, 8, 28, 32, { r: 4 });
    // the meter on the platter rim
    const lv = (st === 'full' ? Math.max(clamp(s.level), 0.95) : clamp(s.level)) * arrive(s.since, 0.6);
    g.circle(C[0], C[1], R, { role: 'dim', opacity: 0.6 });
    if (lv > 0.01) g.arc(C[0], C[1], R, 0, Math.min(359.9, lv * 360), { role: 'accent', opacity: st === 'full' ? 0.55 + 0.45 * pulse(s.t, 1.2) : 1 });
    g.circle(C[0], C[1], 2, { role: 'fill' });
    // the arm
    let a;
    if (st === 'active') {
      const p = s.phase(LOOP) * Math.PI * 2;
      const u = 0.5 + 0.32 * Math.sin(p) + 0.18 * Math.sin(3 * p + 0.6);
      a = lerp(A_IN, A_OUT, clamp(u));
    } else if (st === 'idle') a = lerp(A_OUT, A_PARK, arrive(s.since, 0.5));
    else a = lerp(A_IN, A_OUT, 0.5);
    const [hx, hy] = g.polar(P[0], P[1], L, a);
    g.line(P[0], P[1], hx, hy, { role: 'line', weight: 0.85 });
    g.circle(P[0], P[1], 2.2, { role: 'line', weight: 0.85 });
    g.dot(hx, hy, 1.5, { role: st === 'active' ? 'spark' : 'fill' });
    // activity light: flickers while active
    const p = s.phase(LOOP);
    const io = st === 'active' ? (Math.sin(p * Math.PI * 2 * 7) > 0.1 || Math.sin(p * Math.PI * 2 * 3 + 1) > 0.6 ? 1 : 0.25) : st === 'full' ? 1 : 0.3;
    g.dot(15.5, 35, 1.5, { role: st === 'idle' ? 'dim' : 'spark', opacity: io });
  },
});

sources.prism-deck/src/glyphs/system/gpu.js:
// gpu — a graphics card: board, a fan, heatsink fins, edge connector. The fins are the
// meter (1–3 light by level) and the fan spins faster the higher the load — a whole
// number of blade-steps per loop, so the spin is seamless. idle: zero-RPM, the fan rests.
import { defineGlyph } from '../_glyph.js';
import { arrive, clamp } from '../../scene/easing.js';
import { curve } from './_kit.js';

const FX = 18, FY = 22, FR = 8;           // fan
const FINS = [16.5, 22, 27.5];            // fin rows (top → bottom)
const BLADES = 3;
const LOOP = 1.2;

export default defineGlyph({
  id: 'gpu',
  title: 'GPU',
  category: 'system',
  tags: ['gpu', 'graphics', 'video card', 'fan', 'system', 'performance', 'load'],
  states: { busy: 'active', idle: 'idle' },
  loop: LOOP,
  draw(g, s) {
    const busy = s.state === 'busy';
    g.rect(7, 11, 34, 22, { r: 3.5 });
    // edge connector, keyed
    g.line(12, 36.5, 15.5, 36.5, { role: 'dim' });
    g.line(19, 36.5, 30, 36.5, { role: 'dim' });
    // fan: ring, hub, three swept blades
    g.circle(FX, FY, FR, { role: 'dim', opacity: 0.8 });
    const lv = clamp(s.level);
    const steps = busy ? 1 + Math.round(lv * 2) : 0;           // 0–3 blade-steps (120°) per loop
    const spin = (steps * 360 * s.phase(LOOP)) / BLADES;
    for (let b = 0; b < BLADES; b++) {
      const a = (b * 360) / BLADES + spin;
      const [x0, y0] = g.polar(FX, FY, 2.6, a), [xc, yc] = g.polar(FX, FY, 5.6, a + 14), [x1, y1] = g.polar(FX, FY, 5.9, a + 70);
      g.path(curve([x0, y0], [xc, yc], [x1, y1]), { role: busy ? 'accent' : 'line', weight: 0.9 });
    }
    g.dot(FX, FY, 1.7, { role: busy ? 'spark' : 'fill' });
    // fins: the load meter, lighting bottom → top
    const lit = busy ? Math.ceil(lv * 3 - 1e-9) : 0;
    FINS.forEach((y, i) => {
      const on = 2 - i < lit;
      const k = on ? arrive(Math.max(0, s.since - (2 - i) * 0.1), 0.36) : 0;
      g.line(30, y, 36.5, y, { role: on ? 'accent' : 'dim', opacity: on ? 0.4 + 0.6 * k : 0.7 });
    });
  },
});

sources.prism-deck/src/glyphs/system/memory.js:
// memory — a RAM module: board, four chips, keyed contacts. The chips are the meter:
// they fill by level (a partial chip fills from the bottom), and while in use a refresh
// shimmer runs across the lit chips. high: the meter pins near full and the top chip blinks.
import { defineGlyph } from '../_glyph.js';
import { arrive, clamp } from '../../scene/easing.js';
import { bump } from './_kit.js';

const CHIPS = [11, 18, 25, 32];               // chip x (w 5, gaps 2)
const CW = 5, CY = 15.5, CH = 10.5;
const PINS = [11.5, 15.5, 19.5, 28.5, 32.5, 36.5]; // contacts, keyed by the gap at the center
const LOOP = 1.6;

export default defineGlyph({
  id: 'memory',
  title: 'Memory',
  category: 'system',
  tags: ['memory', 'ram', 'dimm', 'system', 'usage', 'performance'],
  states: { normal: 'active', high: 'warn' },
  loop: LOOP,
  draw(g, s) {
    g.rect(7, 11.5, 34, 18.5, { r: 3 });
    for (const x of PINS) g.line(x, 33.5, x, 37, { role: 'dim' });
    const high = s.state === 'high';
    const lv = (high ? Math.max(clamp(s.level), 0.92) : clamp(s.level)) * arrive(s.since, 0.5);
    const fillN = lv * 4;
    const p = s.phase(LOOP);
    CHIPS.forEach((x, i) => {
      const f = clamp(fillN - i);
      const top = i === Math.ceil(fillN) - 1;
      if (f < 1) g.rect(x, CY, CW, CH, { r: 1.2, role: 'dim', fill: true, opacity: 0.32 }); // a ghost chip
      if (f <= 0.04) return;
      // in use: a refresh shimmer travels across the chips; high: the top chip blinks
      let op = 0.78 + 0.22 * bump(p, (i + 0.5) / 4, 0.3, true);
      if (high && top) op = 0.3 + 0.7 * (0.5 + 0.5 * Math.cos(p * Math.PI * 4));
      const h = CH * f;
      g.rect(x, CY + CH - h, CW, h, { r: Math.min(1.2, h / 2), role: 'accent', fill: true, opacity: op });
    });
  },
});

sources.prism-deck/src/glyphs/system/network.js:
// network — traffic in and out: a down arrow and an up arrow. online: the shafts turn
// into packet streams flowing each way, faster with the level (whole dash periods per
// loop, so the flow is seamless). idle: quiet solid arrows. offline: the strike draws in.
import { defineGlyph } from '../_glyph.js';
import { arrive, clamp } from '../../scene/easing.js';
import { strike } from './_kit.js';

const XD = 16.5, XU = 31.5;        // down arrow (left), up arrow (right)
const TOP = 10, BOT = 38, HW = 5.5; // shaft span + chevron half-width
const DASH = 3.5, GAP = 3.5, PER = DASH + GAP;
const LOOP = 1.2;

/** Packets on a vertical shaft between y0 (tail) and y1 (head), moving toward the head. */
function packets(g, x, y0, y1, off, opts) {
  const dir = Math.sign(y1 - y0), len = Math.abs(y1 - y0);
  for (let u = -PER + (off % PER); u < len; u += PER) {
    const a = Math.max(0, u), b = Math.min(len, u + DASH);
    if (b - a > 0.4) g.line(x, y0 + dir * a, x, y0 + dir * b, opts);
  }
}

export default defineGlyph({
  id: 'network',
  title: 'Network',
  category: 'system',
  tags: ['network', 'traffic', 'upload', 'download', 'ethernet', 'lan', 'throughput'],
  states: { online: 'active', idle: 'idle', offline: 'neg' },
  loop: LOOP,
  draw(g, s) {
    const st = s.state;
    const role = st === 'offline' ? 'dim' : 'line';
    // heads
    g.polyline([[XD - HW, BOT - HW], [XD, BOT], [XD + HW, BOT - HW]], { role });
    g.polyline([[XU - HW, TOP + HW], [XU, TOP], [XU + HW, TOP + HW]], { role });
    if (st !== 'online') {
      g.line(XD, TOP, XD, BOT, { role });
      g.line(XU, BOT, XU, TOP, { role });
      if (st === 'offline') strike(g, s, { from: [9.5, 11.5], to: [38.5, 36.5] });
      return;
    }
    // online: packet streams; speed = whole periods per loop by level
    const k = arrive(s.since, 0.3);
    const steps = 1 + Math.round(clamp(s.level) * 2);
    const off = s.phase(LOOP) * PER * steps;
    packets(g, XD, TOP, BOT - 1, off, { role: 'accent', opacity: k });
    packets(g, XU, BOT, TOP + 1, off + PER / 2, { role: 'accent', opacity: k });
    if (k < 1) { g.line(XD, TOP, XD, BOT, { role: 'line', opacity: 1 - k }); g.line(XU, BOT, XU, TOP, { role: 'line', opacity: 1 - k }); }
  },
});

sources.prism-deck/src/glyphs/system/wifi.js:
// wifi — a fan of three waves over a base dot. connected: 1–3 waves light by signal
// level (the rest stay as faint ghosts), drawing out from the dot on arrival, and the
// outermost lit wave breathes. searching: a ripple runs dot → outer wave and repeats.
// off: everything goes quiet and the strike draws in.
import { defineGlyph } from '../_glyph.js';
import { arrive, clamp, pulse } from '../../scene/easing.js';
import { bump, strike } from './_kit.js';

const CX = 24, CY = 34.5;          // the waves' common center (the base dot)
const R = [8, 15, 22];             // wave radii: 12.5 … 37.1 high, 7.8 … 40.2 wide
const HALF = [44, 46, 47.5];       // half-angle of each wave (deg)
const LOOP = 2.4;

export default defineGlyph({
  id: 'wifi',
  title: 'Wi-Fi',
  category: 'system',
  tags: ['wifi', 'wireless', 'signal', 'network', 'connection', 'strength'],
  states: { connected: 'active', searching: 'busy', off: 'off' },
  loop: LOOP,
  draw(g, s) {
    const st = s.state;
    if (st === 'off') {
      R.forEach((r, i) => g.arc(CX, CY, r, -HALF[i], HALF[i], { role: 'dim', opacity: 0.55 }));
      g.circle(CX, CY, 2.6, { role: 'dim', fill: true, opacity: 0.55 });
      strike(g, s, { from: [11.5, 11.5], to: [36.5, 36.5] });
      return;
    }
    if (st === 'searching') {
      // one ripple per 1.2 s: dot (0) → waves 1 … 3, wrapping back to the dot
      const w = (s.phase(1.2) * 4) % 4;
      R.forEach((r, i) => {
        const hot = Math.max(bump(w, i + 1, 1.1), bump(w + 4, i + 1, 1.1));
        g.arc(CX, CY, r, -HALF[i], HALF[i], { role: 'dim', opacity: 0.4 });
        if (hot > 0.02) g.arc(CX, CY, r, -HALF[i], HALF[i], { role: 'line', opacity: hot });
      });
      const dot = Math.max(bump(w, 0, 1.1), bump(w, 4, 1.1));
      g.circle(CX, CY, 2.6, { role: 'dim', fill: true, opacity: 0.6 });
      g.dot(CX, CY, 2.6, { role: 'spark', opacity: dot });
      return;
    }
    // connected: lit waves by level
    const bars = Math.ceil(clamp(s.level) * 3 - 1e-9);
    R.forEach((r, i) => {
      if (i >= bars) { g.arc(CX, CY, r, -HALF[i], HALF[i], { role: 'dim', opacity: 0.32 }); return; }
      const k = arrive(Math.max(0, s.since - i * 0.08), 0.42);
      const h = HALF[i] * k;
      if (h < 0.5) return;
      const outer = i === bars - 1 && bars > 1;
      g.arc(CX, CY, r, -h, h, { role: i === 0 ? 'line' : 'accent', opacity: outer ? 0.55 + 0.45 * pulse(s.t, LOOP) : 1 });
    });
    g.circle(CX, CY, 2.6, { role: 'fill' });
  },
});

sources.prism-deck/src/glyphs/time/_dial.js:
// Shared geometry for the I3 glyph families (time · nav · productivity · home).
// Pure path math in grid units — no roles, no colors.
import { P } from '../../scene/svg.js';

const K = 2 / 3; // quadratic → cubic control-point factor
import { polar } from '../../scene/shapes.js';

/** A pie wedge from the center (degrees, 0 = 12 o'clock, clockwise a0 → a1). '' when empty. */
export function wedge(cx, cy, r, a0, a1) {
  const span = a1 - a0;
  if (span <= 0.25) return '';
  if (span >= 359.75) return P().M(cx, cy - r).A(r, r, 0, 0, 1, cx, cy + r).A(r, r, 0, 0, 1, cx, cy - r).Z().d;
  const [ax, ay] = polar(cx, cy, r, a0), [bx, by] = polar(cx, cy, r, a1);
  return P().M(cx, cy).L(ax, ay).A(r, r, 0, span > 180, true, bx, by).Z().d;
}

/** A smooth open path through points (Catmull-Rom → cubic), for wisps and cords. */
export function smooth(pts) {
  const p = P().M(...pts[0]);
  for (let i = 0; i < pts.length - 1; i++) {
    const a = pts[i - 1] || pts[i], b = pts[i], c = pts[i + 1], d = pts[i + 2] || c;
    p.C(b[0] + (c[0] - a[0]) / 6, b[1] + (c[1] - a[1]) / 6, c[0] - (d[0] - b[0]) / 6, c[1] - (d[1] - b[1]) / 6, c[0], c[1]);
  }
  return p.d;
}

/** Point along a polyline at u (0–1 by length). */
export function along(pts, u) {
  const seg = [];
  let total = 0;
  for (let i = 1; i < pts.length; i++) { const l = Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]); seg.push(l); total += l; }
  let d = Math.max(0, Math.min(1, u)) * total;
  for (let i = 0; i < seg.length; i++) {
    if (d <= seg[i] || i === seg.length - 1) { const f = seg[i] ? Math.min(1, d / seg[i]) : 0; return [pts[i][0] + (pts[i + 1][0] - pts[i][0]) * f, pts[i][1] + (pts[i + 1][1] - pts[i][1]) * f]; }
    d -= seg[i];
  }
  return pts[pts.length - 1];
}

/** Sample an arc into points (for along()). */
export function arcPoints(cx, cy, r, a0, a1, steps = 12) {
  return Array.from({ length: steps + 1 }, (_, i) => polar(cx, cy, r, a0 + ((a1 - a0) * i) / steps));
}

/** A closed polygon with rounded corners (radius per corner, or one radius for all). */
export function roundedPoly(pts, radii) {
  const N = pts.length, rs = Array.isArray(radii) ? radii : pts.map(() => radii || 0);
  const p = P();
  const cut = (a, b, r) => { const l = Math.hypot(b[0] - a[0], b[1] - a[1]) || 1, f = Math.min(r, l / 2) / l; return [a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f]; };
  for (let i = 0; i < N; i++) {
    const prev = pts[(i + N - 1) % N], c = pts[i], next = pts[(i + 1) % N], r = rs[i];
    const a = cut(c, prev, r), b = cut(c, next, r);
    if (i === 0) p.M(...a); else p.L(...a);
    if (r > 0.01) p.C(a[0] + (c[0] - a[0]) * K, a[1] + (c[1] - a[1]) * K, b[0] + (c[0] - b[0]) * K, b[1] + (c[1] - b[1]) * K, b[0], b[1]); // a rounded corner as a cubic (no Q: themes read Q as lettering)
  }
  return p.Z().d;
}

/** A smooth closed path through points (closed Catmull-Rom → cubic). */
export function smoothClosed(pts) {
  const N = pts.length, p = P().M(...pts[0]);
  for (let i = 0; i < N; i++) {
    const a = pts[(i + N - 1) % N], b = pts[i], c = pts[(i + 1) % N], d = pts[(i + 2) % N];
    p.C(b[0] + (c[0] - a[0]) / 6, b[1] + (c[1] - a[1]) / 6, c[0] - (d[0] - b[0]) / 6, c[1] - (d[1] - b[1]) / 6, c[0], c[1]);
  }
  return p.Z().d;
}

sources.prism-deck/src/glyphs/time/_digits.js:
// Instrument digits for glyphs that show a number (calendar date, thermostat setpoint).
//
// A 3 × 5 stroke numeral drawn with rounded corners on a 2.4-unit lattice whose nodes
// are the cell centers of the deck's 15 × 15 pixel matrix (x = 7.2 + 2.4 · col). In
// vector themes it reads as a rounded LCD / instrument face; pixel and phosphor
// themes rasterize the same strokes into a clean 3 × 5 bitmap numeral instead of
// mush. Strings center on x = 24 (col 7) exactly: n digits span 4n − 1 cells.
import { P } from '../../scene/svg.js';

const K = 2 / 3; // quadratic → cubic control-point factor

const PITCH = 2.4, ORIGIN = 7.2;
export const col = (c) => ORIGIN + PITCH * c;
export const row = (r) => ORIGIN + PITCH * r;

// strokes per digit: lists of [x, y, cornerRadius] in lattice units (x 0–2, y 0–4); 'z' closes
const D = {
  0: [['z', [0, 0, 1], [2, 0, 1], [2, 4, 1], [0, 4, 1]]],
  1: [[[0, 1, 0], [1, 0, 0.35], [1, 4, 0]]],
  2: [[[0, 0, 0], [2, 0, 1], [2, 2, 1], [0, 2, 1], [0, 4, 0], [2, 4, 0]]],
  3: [[[0, 0, 0], [2, 0, 1], [2, 4, 1], [0, 4, 0]], [[1, 2, 0], [2, 2, 0]]],
  4: [[[0, 0, 0], [0, 2, 0.6], [2, 2, 0]], [[2, 0, 0], [2, 4, 0]]],
  5: [[[2, 0, 0], [0, 0, 0], [0, 2, 0], [2, 2, 1], [2, 4, 1], [0, 4, 0]]],
  6: [[[2, 0, 0], [0, 0, 1], [0, 4, 1], [2, 4, 1], [2, 2, 1], [0, 2, 0]]],
  7: [[[0, 0, 0], [2, 0, 0.3], [1, 2.6, 0.6], [1, 4, 0]]],
  8: [['z', [0, 0, 1], [2, 0, 1], [2, 2, 1], [0, 2, 1]], ['z', [0, 2, 1], [2, 2, 1], [2, 4, 1], [0, 4, 1]]],
  9: [[[0, 4, 0], [2, 4, 1], [2, 0, 1], [0, 0, 1], [0, 2, 1], [2, 2, 0]]],
};

function strokePath(list, ox, oy) {
  const closed = list[0] === 'z';
  const pts = (closed ? list.slice(1) : list).map(([x, y, r]) => [ox + x * PITCH, oy + y * PITCH, (r || 0) * PITCH]);
  const N = pts.length, p = P();
  const cut = (a, b, r) => { const l = Math.hypot(b[0] - a[0], b[1] - a[1]) || 1, f = Math.min(r, l / 2) / l; return [a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f]; };
  for (let i = 0; i < N; i++) {
    const c = pts[i], r = c[2];
    const prev = closed ? pts[(i + N - 1) % N] : pts[i - 1], next = closed ? pts[(i + 1) % N] : pts[i + 1];
    if (!prev || !next || r < 0.01) { if (i === 0) p.M(c[0], c[1]); else p.L(c[0], c[1]); continue; }
    const a = cut(c, prev, r), b = cut(c, next, r);
    if (i === 0) p.M(...a); else p.L(...a);
    p.C(a[0] + (c[0] - a[0]) * K, a[1] + (c[1] - a[1]) * K, b[0] + (c[0] - b[0]) * K, b[1] + (c[1] - b[1]) * K, b[0], b[1]); // a rounded corner as a cubic (no Q: themes read Q as lettering)
  }
  if (closed) { const c = pts[0], r = c[2]; if (r >= 0.01) { const a = cut(c, pts[N - 1], r); p.L(...a); } p.Z(); }
  return p.d;
}

/** Draw a numeral string (digits only) centered on x = 24, top at lattice row `top`. */
export function digits(g, str, { top = 8, role = 'line', weight = 0.85, opacity = 1 } = {}) {
  const s = String(str).replace(/[^0-9]/g, '');
  const c0 = 7 - (4 * s.length - 1 - 1) / 2; // first digit's left column
  [...s].forEach((ch, i) => {
    for (const st of D[ch]) g.path(strokePath(st, col(c0 + i * 4), row(top)), { role, weight, opacity, join: 'round', cap: 'round', fill: false });
  });
}

sources.prism-deck/src/glyphs/time/alarm.js:
// alarm — a twin-bell alarm clock. off: quiet. set: the hands light, the hammer rests.
// ringing: the clock shakes in bursts, the hammer strikes bell to bell and the air
// beside it trembles (1.5 s loop: a one-second burst, half a second's breath).
import { defineGlyph } from '../_glyph.js';
import { arrive, phase, smoothstep } from '../../scene/easing.js';
import { P } from '../../scene/svg.js';
import { polar } from '../../scene/shapes.js';

const CX = 24, CY = 27, R = 12;

/** A bell dome facing direction `deg`, its flat side toward the clock. */
function bell(deg) {
  const b = polar(CX, CY, 15.5, deg);
  const [x0, y0] = polar(b[0], b[1], 5, deg - 90), [x1, y1] = polar(b[0], b[1], 5, deg + 90);
  return P().M(x0, y0).A(5, 5, 0, 0, 1, x1, y1).Z().d;
}

export default defineGlyph({
  id: 'alarm',
  title: 'Alarm',
  category: 'time',
  tags: ['alarm', 'wake', 'ring', 'reminder', 'bell', 'clock', 'time'],
  states: { off: 'off', set: 'active', ringing: 'alert' },
  loop: 1.5,
  draw(g, s) {
    const ringing = s.state === 'ringing', set = s.state !== 'off';
    const p = phase(s.t, 1.5);
    const env = ringing ? smoothstep(0, 0.06, p) * (1 - smoothstep(0.6, 0.68, p)) : 0;
    const shake = 7 * Math.sin((s.t / 0.25) * Math.PI * 2) * env;
    const k = arrive(s.since, 0.4);

    g.group({ rotate: shake, origin: [CX, CY] }, () => {
      g.path(bell(-42), { role: 'fill', opacity: 0.92 });
      g.path(bell(42), { role: 'fill', opacity: 0.92 });
      // hammer: rests upright; strikes left / right while ringing
      const swing = ringing ? 24 * Math.sin((s.t / 0.25) * Math.PI * 2 + Math.PI / 2) * env : 0;
      g.group({ rotate: swing, origin: [CX, CY - R] }, () => {
        g.line(CX, CY - R, CX, 10.5, { role: 'line', weight: 0.9 });
        g.dot(CX, 9.5, 1.7, { role: ringing ? 'spark' : 'fill' });
      });
      g.circle(CX, CY, R);
      // legs
      for (const a of [145, 215]) {
        const [x0, y0] = polar(CX, CY, R + 0.5, a), [x1, y1] = polar(CX, CY, 16.2, a);
        g.line(x0, y0, x1, y1, { role: 'line' });
      }
      // hands at ten past ten; set lights the minute hand
      const [hx, hy] = polar(CX, CY, 6, 300), [mx, my] = polar(CX, CY, 8.5 * (set ? 0.75 + 0.25 * k : 1), 60);
      g.line(CX, CY, hx, hy, { role: 'line' });
      g.line(CX, CY, mx, my, { role: set ? 'accent' : 'dim' });
      g.dot(CX, CY, 1.7, { role: 'fill' });
    });
    if (ringing && env > 0.01) {
      // the air trembles beside the clock
      const flick = 0.45 + 0.55 * Math.abs(Math.sin((s.t / 0.25) * Math.PI * 2));
      for (const [a0, a1] of [[248, 292], [68, 112]]) g.arc(CX, CY, 16.5, a0, a1, { role: 'accent', weight: 0.75, opacity: env * flick });
    }
  },
});

sources.prism-deck/src/glyphs/time/calendar.js:
// calendar — a bound page showing a date. The day comes from params.day (1–31; the
// icons facet passes today's date from ctx.clock when its Day param is 0).
// event: the header lights and the date takes the accent — something is on today.
// Every state change turns the page: the new date rises into place as the header settles.
import { defineGlyph } from '../_glyph.js';
import { arrive, lerp } from '../../scene/easing.js';
import { P } from '../../scene/svg.js';
import { digits } from './_digits.js';

const X0 = 9.5, X1 = 38.5, Y0 = 11, Y1 = 40, HEAD = 19, RAD = 4;

export default defineGlyph({
  id: 'calendar',
  title: 'Calendar',
  category: 'time',
  tags: ['calendar', 'date', 'day', 'schedule', 'event', 'agenda', 'meeting'],
  states: { date: 'idle', event: 'active' },
  draw(g, s) {
    const event = s.state === 'event';
    const k = arrive(s.since, 0.45);
    const raw = Math.round(Number(s.params.day));
    const day = raw >= 1 && raw <= 31 ? raw : 17;
    if (event) {
      // the header band lights from the binding down
      const hb = lerp(Y0 + RAD, HEAD, k);
      g.path(P().M(X0, hb).V(Y0 + RAD).A(RAD, RAD, 0, 0, 1, X0 + RAD, Y0).H(X1 - RAD).A(RAD, RAD, 0, 0, 1, X1, Y0 + RAD).V(hb).Z().d, { role: 'accent', fill: true, opacity: 0.9 });
    }
    g.rect(X0, Y0, X1 - X0, Y1 - Y0, { r: RAD });
    g.line(X0, HEAD, X1, HEAD, { role: event ? 'line' : 'dim' });
    // binder rings
    for (const x of [17.5, 30.5]) g.line(x, 7.5, x, 14, { role: 'line', weight: 1.05 });
    // the date rises into place with the page turn
    g.group({ y: 3.5 * (1 - k), opacity: k }, () => digits(g, day, { top: 7, role: event ? 'accent' : 'line' }));
  },
});

sources.prism-deck/src/glyphs/time/clock.js:
// clock — an analog face. Shows params.h / params.m when given; otherwise the minute hand sweeps once per loop.
import { defineGlyph } from '../_glyph.js';

export default defineGlyph({
  id: 'clock',
  title: 'Clock',
  category: 'time',
  tags: ['clock', 'time', 'hour', 'analog'],
  loop: 12,
  draw(g, s) {
    g.circle(24, 24, 17);
    for (const a of [0, 90, 180, 270]) {
      const [x1, y1] = g.polar(24, 24, 13, a), [x2, y2] = g.polar(24, 24, 15.5, a);
      g.line(x1, y1, x2, y2, { role: 'dim' });
    }
    const m = typeof s.params.m === 'number' ? s.params.m + (s.params.s || 0) / 60 : s.phase(12) * 60;
    const h = typeof s.params.h === 'number' ? (s.params.h % 12) + m / 60 : 10 + m / 60;
    const hand = (deg, len, opts) => { const [x, y] = g.polar(24, 24, len, deg); g.line(24, 24, x, y, opts); };
    hand(h * 30, 8.5, { role: 'line', weight: 1.1 });
    hand(m * 6, 12.5, { role: 'accent' });
    g.dot(24, 24, 1.8);
  },
});

sources.prism-deck/src/glyphs/time/stopwatch.js:
// stopwatch — crown, side button, one sweep hand. ready: hand at 12.
// running: the crown clicks in and the hand sweeps from 12 (one turn per 4 s of
// `since`, so a running key starts at zero), trailing a fading wedge of light.
// paused: the hand holds at `level` of a turn and blinks, the way a stopped watch does.
import { defineGlyph } from '../_glyph.js';
import { arrive, pulse, clamp } from '../../scene/easing.js';
import { wedge } from './_dial.js';

const CX = 24, CY = 26.5, R = 14;
const LAP = 4; // seconds per turn of the sweep hand

export default defineGlyph({
  id: 'stopwatch',
  title: 'Stopwatch',
  category: 'time',
  tags: ['stopwatch', 'chrono', 'elapsed', 'lap', 'time', 'race'],
  states: { ready: 'idle', running: 'active', paused: 'idle' },
  loop: 4,
  draw(g, s) {
    const running = s.state === 'running', paused = s.state === 'paused';
    // crown: dips as the state changes (the click), springs back
    const click = s.state === 'ready' ? 0 : 1.6 * Math.sin(Math.PI * clamp(s.since / 0.28));
    g.group({ y: click }, () => {
      g.line(CX, 8, CX, 12.5, { role: 'line' });
      g.line(20.5, 8, 27.5, 8, { role: 'line', weight: 1.1 });
    });
    g.circle(CX, CY, R);
    // side button at 45°
    const [bx0, by0] = g.polar(CX, CY, R + 2.2, 45), [bx1, by1] = g.polar(CX, CY, R + 4.4, 45);
    g.line(bx0, by0, bx1, by1, { role: 'line', weight: 1.05 });
    for (const a of [90, 180, 270]) {
      const [x1, y1] = g.polar(CX, CY, 9.5, a), [x2, y2] = g.polar(CX, CY, 11.5, a);
      g.line(x1, y1, x2, y2, { role: 'dim' });
    }
    const top = g.polar(CX, CY, 9.5, 0), top2 = g.polar(CX, CY, 11.5, 0);
    g.line(top[0], top[1], top2[0], top2[1], { role: running ? 'accent' : 'dim' });

    let ang = 0, op = 1;
    if (running) ang = ((s.since / LAP) % 1) * 360;
    if (paused) { ang = clamp(s.level) * 360; op = 0.35 + 0.65 * (pulse(s.t, 1) > 0.35 ? 1 : 0.25); }
    if (running) {
      // the sweep: a wedge of light behind the hand, fading in as the watch starts
      const k = arrive(s.since, 0.4);
      const trail = Math.min(ang, 70);
      const d = wedge(CX, CY, 10.5, ang - trail, ang);
      if (d) g.path(d, { role: 'accent', fill: true, opacity: 0.34 * k });
    }
    const [hx, hy] = g.polar(CX, CY, 10.5, ang), [tx, ty] = g.polar(CX, CY, 3, ang + 180);
    g.line(tx, ty, hx, hy, { role: running || paused ? 'accent' : 'line', opacity: op });
    g.dot(CX, CY, 2, { role: 'fill' });
  },
});

sources.prism-deck/src/glyphs/time/timer.js:
// timer — a countdown dial: the wedge of time remaining, measured clockwise to 12.
// ready: the wedge winds up to `level` (the share of the dial that is set).
// running: the wedge lights and drains in real time — `params.minutes` is the whole
// dial, so a facet needs only state + since — and a spark on the rim beats each second.
// done: the dial is empty and the face flashes with a burst of light from the hub.
import { defineGlyph } from '../_glyph.js';
import { arrive, pulse, phase, lerp, clamp, outExpo } from '../../scene/easing.js';
import { wedge } from './_dial.js';

const C = 24, R = 16.5, W = 12.5; // rim radius · wedge radius

export default defineGlyph({
  id: 'timer',
  title: 'Timer',
  category: 'time',
  tags: ['timer', 'countdown', 'kitchen', 'pomodoro', 'remaining', 'time'],
  states: { ready: 'idle', running: 'active', done: 'alert' },
  loop: 1,
  draw(g, s) {
    const k = arrive(s.since, 0.5);
    const minutes = typeof s.params.minutes === 'number' && s.params.minutes > 0 ? s.params.minutes : 5;
    const set = clamp(s.level);
    let rem = set;
    if (s.state === 'ready') rem = set * k; // winding up
    if (s.state === 'running') rem = clamp(set - s.since / (minutes * 60));
    if (s.state === 'done') rem = 0;
    const expired = s.state === 'done' || rem <= 0.0005;

    g.circle(C, C, R, { role: expired && s.state !== 'ready' ? 'accent' : 'line' });
    const a = (1 - rem) * 360; // the leading edge, sweeping clockwise as time runs out
    const d = wedge(C, C, W, a, 360);
    if (d) {
      if (s.state === 'running') {
        if (k < 1) g.path(d, { role: 'fill', fill: true, opacity: 0.3 * (1 - k) });
        g.path(d, { role: 'accent', fill: true, opacity: lerp(0.3, 0.88, k) });
      } else g.path(d, { role: 'fill', fill: true, opacity: 0.32 });
    }
    // the hand rides the leading edge
    const [hx, hy] = g.polar(C, C, W, expired ? 0 : a);
    g.line(C, C, hx, hy, { role: expired && s.state !== 'ready' ? 'accent' : 'line' });
    g.dot(C, C, 2.2, { role: 'fill' });

    if (s.state === 'running' && !expired) {
      // one beat per second on the rim, just ahead of the edge
      const [sx, sy] = g.polar(C, C, 14.5, a);
      const b = pulse(s.t, 1);
      g.dot(sx, sy, 1.3 + 0.5 * b, { opacity: 0.55 + 0.45 * b });
    }
    if (expired && s.state !== 'ready') {
      // time's up: rays burst from the hub and fade at the rim, twice a second
      const p = phase(s.t, 0.5), e = outExpo(p);
      const r0 = lerp(4.5, 9.5, e), r1 = lerp(6.5, 13, e), op = (1 - p) * (s.state === 'done' ? k : 1);
      for (let i = 0; i < 8; i++) {
        const ang = 22.5 + i * 45;
        const [x0, y0] = g.polar(C, C, r0, ang), [x1, y1] = g.polar(C, C, r1, ang);
        g.line(x0, y0, x1, y1, { role: 'accent', weight: 0.75, opacity: op });
      }
    }
  },
});

sources.prism-deck/src/hid/features.js:
// Feature reports — byte builders only. Plain node:fs cannot issue ioctl(), so
// these go through linux/prism-deck-hidfeature.py (stdlib python3), which
// enforces the same allowlist. Layouts: research linux.md §2.5.
//
//   gen2 (32 bytes, zero-padded)          gen1 — 2017 original / Mini family (17 or 32 bytes)
//   03 02            show logo            0B 63                 reset / show logo
//   03 05 r g b      fill whole LCD       05 55 AA D1 01 pct    brightness
//   03 06 i r g b    fill key / sensor
//   03 08 pct        brightness 0–100
//   03 0D int32      sleep timeout (s)
//   Galleon (unpadded): 03 27 keep-alive every 500 ms · 03 24 i r g b dial ring pixel
//   GET: gen2 04/05/07 firmware, 06 serial, 08 unit info, 0A sleep; gen1 03 serial, 04 firmware; Studio 11/13

const pad = (bytes, len) => { const a = new Uint8Array(len); a.set(bytes); return a; };
const pct = (p) => Math.max(0, Math.min(100, Math.round(Number(p) || 0)));
const b8 = (v) => Math.max(0, Math.min(255, Math.round(Number(v) || 0)));

/** First feature length to try for a model (gen1 Minis fall back between 32 and 17). */
export const featureLen = (m) => m.feature?.lens?.[0] ?? 32;

export const features = {
  brightness: (m, p, len = featureLen(m)) => (m.feature.kind === 'gen2' ? pad([0x03, 0x08, pct(p)], len) : pad([0x05, 0x55, 0xaa, 0xd1, 0x01, pct(p)], len)),
  showLogo: (m, len = featureLen(m)) => (m.feature.kind === 'gen2' ? pad([0x03, 0x02], len) : pad([0x0b, 0x63], len)),
  fillKey: (key, r, g, b) => pad([0x03, 0x06, b8(key), b8(r), b8(g), b8(b)], 32),
  fillLcd: (r, g, b) => pad([0x03, 0x05, b8(r), b8(g), b8(b)], 32),
  sleepSeconds: (s) => { const a = pad([0x03, 0x0d], 32); new DataView(a.buffer).setInt32(2, Math.max(0, Math.trunc(s) || 0), true); return a; },
  galleonPing: () => new Uint8Array([0x03, 0x27]),
  galleonRingPixel: (i, r, g, b) => new Uint8Array([0x03, 0x24, b8(i), b8(r), b8(g), b8(b)]),
};

/** Physical Galleon ring LED index for dial `encoder` (0 left, 1 right), logical LED i (0–3) — node galleonK100 encoderLed. [UNVERIFIED on hardware] */
export const galleonRingIndex = (encoder, i, offsets = [3, 1]) => (1 - encoder) * 4 + ((i + offsets[encoder]) % 4);

/** Feature GET ids per flavour (read-only). */
export const GETTERS = Object.freeze({
  gen2: { firmware: 0x05, firmwareLd: 0x04, firmwareAp1: 0x07, serial: 0x06, unitInfo: 0x08, sleep: 0x0a, encoderAp2: 0x11, encoderLd: 0x13 },
  gen1: { serial: 0x03, firmware: 0x04 },
});

/** Decode a serial / firmware GET response to ASCII. */
export function decodeGet(m, id, bytes) {
  const b = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  const ascii = (from, to = b.length) => String.fromCharCode(...b.subarray(from, to)).replace(/\0.*$/s, '').trim();
  if (m.feature.kind === 'gen1') return ascii(5);
  if (id === 0x06) return ascii(2, 2 + b[1]);
  if ([0x04, 0x05, 0x07, 0x11, 0x13].includes(id)) return ascii(6, 14);
  return Array.from(b, (x) => x.toString(16).padStart(2, '0')).join('');
}

// The allowlist — kept identical to ALLOWED_SET in linux/prism-deck-hidfeature.py (test/hid.test.js checks both).
// [prefix bytes, number of free argument bytes after the prefix]; every byte after that must be zero padding.
export const ALLOWED_SET = Object.freeze([
  [[0x03, 0x02], 0], // show logo (gen2)
  [[0x03, 0x05], 3], // fill LCD rgb
  [[0x03, 0x06], 4], // fill key idx rgb
  [[0x03, 0x08], 1], // brightness pct
  [[0x03, 0x0d], 4], // sleep timeout int32
  [[0x03, 0x27], 0], // Galleon keep-alive
  [[0x03, 0x24], 4], // Galleon ring pixel idx rgb
  [[0x05, 0x55, 0xaa, 0xd1, 0x01], 1], // gen1 brightness pct
  [[0x0b, 0x63], 0], // gen1 reset / logo
]);
export const ALLOWED_GET = Object.freeze([0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x0a, 0x11, 0x13]);

/** null when `bytes` is an allowed SET feature report, else the reason. */
export function checkFeature(bytes) {
  const b = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  if (b.length < 2 || b.length > 64) return `length ${b.length} outside 2–64`;
  for (const [prefix, args] of ALLOWED_SET) {
    if (b.length < prefix.length || !prefix.every((x, i) => b[i] === x)) continue;
    const end = prefix.length + args;
    if (b.length < end) return `truncated ${prefix.map((x) => x.toString(16)).join(' ')} report`;
    for (let i = end; i < b.length; i++) if (b[i] !== 0) return `non-zero padding at byte ${i}`;
    if (prefix[1] === 0x08 && b[2] > 100) return 'brightness above 100';
    if (prefix[0] === 0x05 && b[5] > 100) return 'brightness above 100';
    return null;
  }
  return `feature ${Array.from(b.subarray(0, 2), (x) => x.toString(16).padStart(2, '0')).join(' ')} is not on the allowlist`;
}

sources.prism-deck/src/hid/input.js:
// Input reports (device → host). hidraw read() returns ONE report per call with
// the report id at raw[0]. Layouts: research linux.md §2.4.
//
//   gen1 (orig, mini)  raw[0]=01, raw[1+i] = key i (orig: wire index, right-to-left per row)
//   gen2               raw[0]=01, raw[1]=cmd, raw[2..3]=payload length LE, payload from raw[4]
//     cmd 00  keys      raw[4+i] = key i (Neo: keys 0–7, touch sensors 8 left / 9 right)
//     cmd 02  touch     raw[4] 1 tap / 2 press (long) / 3 flick; x raw[6..7], y raw[8..9]; flick x2/y2 raw[10..13]
//     cmd 03  encoders  raw[4]=00 press state raw[5+i] (edge-detected here); raw[4]=01 rotate int8 raw[5+i] (+ = clockwise)
//     cmd 04  NFC       ascii raw[4 .. 4+len), len = raw[2..3] (Studio)
//
// Events: { type: 'down' | 'up', key, sensor? } · { type: 'rotate', dial, ticks } · { type: 'dialDown' | 'dialUp', dial }
//         { type: 'touch', gesture: 'tap' | 'press' | 'flick', x, y, x2?, y2? } · { type: 'nfc', id }

import { hidKey } from './models.js';

const GESTURES = [null, 'tap', 'press', 'flick'];

/** A stateful parser for one device (it edge-detects keys and dial presses). parse(report) → events[]. */
export function createInputParser(m) {
  const keys = new Uint8Array(m.inputs);
  const dials = new Uint8Array(m.encoders || 0);
  const events = [];
  const key = (k, s) => {
    s = s ? 1 : 0;
    if (s === keys[k]) return;
    keys[k] = s;
    const ev = { type: s ? 'down' : 'up', key: k };
    if (k >= m.keys) ev.sensor = k - m.keys;
    events.push(ev);
  };
  function parse(raw) {
    events.length = 0;
    const r = raw instanceof Uint8Array ? raw : new Uint8Array(raw);
    if (r.length < 2 || r[0] !== 0x01) return [];
    if (m.proto !== 'gen2') {
      for (let k = 0; k < m.keys; k++) key(k, r[1 + hidKey(m, k)]);
      return events.slice();
    }
    if (r.length < 4) return [];
    const v = new DataView(r.buffer, r.byteOffset, r.length);
    const cmd = r[1];
    if (cmd === 0x00) {
      for (let k = 0; k < m.inputs && 4 + k < r.length; k++) key(k, r[4 + k]);
    } else if (cmd === 0x02 && m.touch && r.length >= 10) {
      const gesture = GESTURES[r[4]];
      if (gesture) {
        const ev = { type: 'touch', gesture, x: v.getUint16(6, true), y: v.getUint16(8, true) };
        if (r[4] === 3 && r.length >= 14) { ev.x2 = v.getUint16(10, true); ev.y2 = v.getUint16(12, true); }
        events.push(ev);
      }
    } else if (cmd === 0x03 && dials.length && r.length >= 5 + dials.length) {
      for (let i = 0; i < dials.length; i++) {
        if (r[4] === 0x01) { const d = v.getInt8(5 + i); if (d) events.push({ type: 'rotate', dial: i, ticks: d }); }
        else if (r[4] === 0x00) { const s = r[5 + i] ? 1 : 0; if (s !== dials[i]) { dials[i] = s; events.push({ type: s ? 'dialDown' : 'dialUp', dial: i }); } }
      }
    } else if (cmd === 0x04 && m.nfc) {
      const len = Math.min(v.getUint16(2, true), r.length - 4);
      events.push({ type: 'nfc', id: String.fromCharCode(...r.subarray(4, 4 + len)) });
    }
    return events.slice();
  }
  return { parse, state: () => ({ keys: Array.from(keys), dials: Array.from(dials) }) };
}

sources.prism-deck/src/hid/layout.js:
// Layouts — which facet drives which part of a physical deck.
//
//   {
//     "theme": "prism", "mode": "dark",
//     "deck":    "span-first-light",                       a deck-surface facet over everything (optional)
//     "spans":   [{ "facet": "span-waveform", "col": 0, "row": 0, "cols": 4, "rows": 1 }],
//     "keys":    ["icon-mic", null, { "facet": "icon-volume", "state": 1, "params": { … } }]   (or { "5": … })
//     "strip":   "strip-refraction",                       + / + XL: one facet across the whole strip
//     "dials":   ["dial-volume", …],                        + / + XL: one 200×100 segment facet per dial
//     "screen":  "screen-galleon-dashboard",               Galleon 720×384 (4 widgets) · Neo info bar
//     "widgets": { "0,0": "…", "1,1": "…" }                Galleon: per widget ("dial,layer"), galleon-widget facets
//   }
//
// Precedence: deck → spans → keys; strip | dials; screen | widgets. Conflicts are errors.
// resolveLayout(model, spec) → { slots, keyOwner, segOwner, widgetOwner, infobarOwner, problems }

import { findFacet, allFacets } from '../facets/index.js';
import { getDevice } from '../devices.js';
import { SCREEN_TARGETS } from '../scene/context.js';

// API 1.4: Galleon widget art is a 2:1 window (360×180) centred in its 360×192 quadrant (6 px gutters);
// the region write stays 360×192, the gutters are filled with the theme background.
const GW = SCREEN_TARGETS.galleon.widgets;
const widgetArt = (W) => ({ w: GW.w, h: GW.h, padTo: { w: W.w, h: W.h, x: Math.round((W.w - GW.w) / 2), y: GW.insetY ?? Math.round((W.h - GW.h) / 2), bg: 'theme' } });

const DEFAULT_KEYS = ['icon-mic', 'icon-volume', 'icon-play-pause', 'icon-camera', 'icon-broadcast', 'app-cpu-ring', 'icon-clock', 'app-focus-timer',
  'icon-bulb', 'icon-lock', 'icon-wifi', 'icon-battery', 'icon-sync', 'icon-record', 'icon-timer', 'icon-power'];

const entryOf = (e) => (e == null || e === '' ? null : typeof e === 'string' ? { facet: e } : { ...e });

/** The default layout for a model: icons on the keys, volume dials on a strip, the dashboard on a screen. */
export function defaultLayout(model, { find = findFacet, all = allFacets } = {}) {
  const have = (id) => !!find(id);
  const keys = DEFAULT_KEYS.filter(have);
  for (const f of all()) if (keys.length < model.keys && f.surface === 'key' && f.gallery === 'icons' && !keys.includes(f.id)) keys.push(f.id);
  const spec = { keys: keys.slice(0, model.keys) };
  if (model.lcd?.kind === 'strip') { if (have('dial-volume')) spec.dials = Array(model.lcd.segments).fill('dial-volume'); else if (have('strip-refraction')) spec.strip = 'strip-refraction'; }
  if (model.lcd?.kind === 'screen' && have('screen-galleon-dashboard')) spec.screen = 'screen-galleon-dashboard';
  if (model.lcd?.kind === 'infobar' && have('screen-neo-clock')) spec.screen = 'screen-neo-clock';
  return spec;
}

/** Parse "id@col,row,cols,rows" (CLI shorthand for spans). */
export function parseSpanArg(s) {
  const [facet, at] = String(s).split('@');
  if (!at) return { facet };
  const [col, row, cols, rows] = at.split(',').map(Number);
  return { facet, col: col || 0, row: row || 0, ...(cols ? { cols } : {}), ...(rows ? { rows } : {}) };
}

export function resolveLayout(model, spec = {}, { find = findFacet } = {}) {
  const device = getDevice(model.id);
  const problems = [];
  const slots = [];
  const keyOwner = new Map(), segOwner = new Map(), widgetOwner = new Map();
  let infobarOwner = null;
  const L = model.lcd;

  const facetFor = (entry, where, ok) => {
    const f = find(entry.facet);
    if (!f) { problems.push(`${where}: no facet "${entry.facet}" (try: prism-deck list)`); return null; }
    if (f.devices && !f.devices.includes(model.id)) { problems.push(`${where}: ${f.id} only supports ${f.devices.join(', ')}`); return null; }
    const why = ok(f);
    if (why) { problems.push(`${where}: ${f.id} (${f.surface}) ${why}`); return null; }
    return f;
  };
  const slot = (facet, entry, extra) => {
    const s = {
      id: `${extra.kind}:${slots.length}`, facet, state: Math.max(0, Math.trunc(entry.state || 0)), params: entry.params || {},
      value: typeof entry.value === 'number' ? entry.value : undefined, values: null, ticks: 0, targets: [], renderOpts: {}, dials: [], ...extra,
    };
    slots.push(s);
    return s;
  };
  const claimKey = (k, s, where) => {
    if (keyOwner.has(k)) { problems.push(`${where}: key ${k} is already used by ${keyOwner.get(k).facet.id}`); return false; }
    keyOwner.set(k, s); return true;
  };
  const keyPx = model.key;

  // deck: the whole panel
  const deckEntry = entryOf(spec.deck);
  if (deckEntry && model.key) {
    const f = facetFor(deckEntry, 'deck', (x) => (x.surface === 'deck' ? null : 'is not a deck-surface facet'));
    if (f) {
      const s = slot(f, deckEntry, { kind: 'deck' });
      for (let k = 0; k < model.keys; k++) if (claimKey(k, s, 'deck')) s.targets.push({ id: `key:${k}`, type: 'key', key: k, w: keyPx.w, h: keyPx.h });
      if (L?.kind === 'strip') for (let i = 0; i < L.segments; i++) { segOwner.set(i, s); s.dials.push(i); s.targets.push({ id: `seg:${i}`, type: 'lcd', piece: 'segment', index: i, rect: { x: i * 200, y: 0, w: 200, h: 100 }, w: 200, h: 100 }); }
      if (L?.kind === 'screen') { for (let d = 0; d < 2; d++) for (let l = 0; l < 2; l++) widgetOwner.set(`${d},${l}`, s); s.dials = [0, 1]; s.targets.push({ id: 'screen', type: 'lcd', piece: 'screen', rect: { x: 0, y: 0, w: L.w, h: L.h }, w: L.w, h: L.h }); }
      if (L?.kind === 'infobar') { infobarOwner = s; s.targets.push({ id: 'infobar', type: 'lcd', piece: 'screen', rect: { x: 0, y: 0, w: L.w, h: L.h }, w: L.w, h: L.h }); }
    }
  }

  // spans
  for (const [n, raw] of (spec.spans || []).entries()) {
    const e = entryOf(raw);
    if (!e || !model.key) continue;
    const f = facetFor(e, `spans[${n}]`, (x) => (x.surface === 'span' ? null : 'is not a span facet'));
    if (!f) continue;
    const span = { col: e.col || 0, row: e.row || 0, ...(e.cols ? { cols: e.cols } : {}), ...(e.rows ? { rows: e.rows } : {}) };
    const want = { cols: e.cols ?? (f.span.cols === 'all' ? model.cols - span.col : f.span.cols), rows: e.rows ?? (f.span.rows === 'all' ? model.rows - span.row : f.span.rows) };
    if (span.col + want.cols > model.cols || span.row + want.rows > model.rows) { problems.push(`spans[${n}]: ${f.id} ${want.cols}×${want.rows} at ${span.col},${span.row} does not fit the ${model.cols}×${model.rows} grid`); continue; }
    const s = slot(f, e, { kind: 'span', renderOpts: { span: { ...span, cols: want.cols, rows: want.rows } } });
    for (let r = 0; r < want.rows; r++) for (let c = 0; c < want.cols; c++) {
      const k = (span.row + r) * model.cols + span.col + c;
      if (claimKey(k, s, `spans[${n}]`)) s.targets.push({ id: `key:${k}`, type: 'key', key: k, w: keyPx.w, h: keyPx.h });
    }
  }

  // keys
  const keys = Array.isArray(spec.keys) ? spec.keys.map((e, i) => [i, e]) : Object.entries(spec.keys || {}).map(([i, e]) => [Number(i), e]);
  for (const [k, raw] of keys) {
    const e = entryOf(raw);
    if (!e || !model.key) continue;
    if (!(k >= 0 && k < model.keys)) { problems.push(`keys[${k}]: ${model.name} has keys 0–${model.keys - 1}`); continue; }
    if (keyOwner.has(k)) continue; // spans / deck win silently over a default key list
    const f = facetFor(e, `keys[${k}]`, (x) => (x.surface === 'key' ? null : 'is not a key facet (use spans / strip / screen)'));
    if (!f) continue;
    const s = slot(f, e, { kind: 'key' });
    claimKey(k, s, `keys[${k}]`);
    s.targets.push({ id: `key:${k}`, type: 'key', key: k, w: keyPx.w, h: keyPx.h });
  }

  // strip / dials (+, + XL)
  const stripEntry = entryOf(spec.strip);
  if ((stripEntry || spec.dials) && L?.kind !== 'strip') problems.push(`strip/dials: ${model.name} has no touch strip`);
  else if (L?.kind === 'strip') {
    if (stripEntry && !segOwner.size) {
      const f = facetFor(stripEntry, 'strip', (x) => (x.surface === 'strip' && x.segments === 'all' ? null : 'is not a whole-strip facet (segments: all)'));
      if (f) {
        const s = slot(f, stripEntry, { kind: 'strip', renderOpts: { segments: L.segments } });
        for (let i = 0; i < L.segments; i++) { segOwner.set(i, s); s.dials.push(i); s.targets.push({ id: `seg:${i}`, type: 'lcd', piece: 'segment', index: i, rect: { x: i * 200, y: 0, w: 200, h: 100 }, w: 200, h: 100 }); }
      }
    }
    const dials = Array.isArray(spec.dials) ? spec.dials.map((e, i) => [i, e]) : Object.entries(spec.dials || {}).map(([i, e]) => [Number(i), e]);
    for (const [d, raw] of dials) {
      const e = entryOf(raw);
      if (!e) continue;
      if (!(d >= 0 && d < L.segments)) { problems.push(`dials[${d}]: ${model.name} has dials 0–${L.segments - 1}`); continue; }
      if (segOwner.has(d)) { problems.push(`dials[${d}]: segment ${d} is already used by ${segOwner.get(d).facet.id}`); continue; }
      const f = facetFor(e, `dials[${d}]`, (x) => (x.surface === 'strip' && x.segments === 1 ? null : 'is not a one-segment dial facet (segments: 1)'));
      if (!f) continue;
      const s = slot(f, e, { kind: 'segment', renderOpts: { segments: 1, segment: d } });
      segOwner.set(d, s); s.dials.push(d);
      s.targets.push({ id: `seg:${d}`, type: 'lcd', piece: 'segment', index: 0, rect: { x: d * 200, y: 0, w: 200, h: 100 }, w: 200, h: 100 });
    }
  }

  // screen / widgets (Galleon), info bar (Neo)
  const screenEntry = entryOf(spec.screen || spec.infobar);
  if ((screenEntry || spec.widgets) && !(L?.kind === 'screen' || L?.kind === 'infobar')) problems.push(`screen: ${model.name} has no screen`);
  else if (L?.kind === 'infobar' && screenEntry && !infobarOwner) {
    const f = facetFor(screenEntry, 'screen', (x) => (x.surface === 'screen' && x.screens.includes('infobar') ? null : 'does not support the Neo info bar'));
    if (f) {
      const lay = device.screen?.layout || { w: 232, h: 50 };
      const s = slot(f, screenEntry, { kind: 'infobar', renderOpts: { screen: 'infobar' } });
      infobarOwner = s;
      // rendered at the SDK layout (232×50), centred in the 248×58 window the way the Stream Deck app does
      s.targets.push({ id: 'infobar', type: 'lcd', piece: 'screen', rect: { x: 0, y: 0, w: L.w, h: L.h }, w: lay.w, h: lay.h, padTo: { w: L.w, h: L.h } });
    }
  } else if (L?.kind === 'screen') {
    const W = L.widgets;
    if (screenEntry && !widgetOwner.size) {
      const f = facetFor(screenEntry, 'screen', (x) => (x.surface === 'screen' && x.screens.includes('galleon') ? null : 'does not support the Galleon screen'));
      if (f) {
        const s = slot(f, screenEntry, { kind: 'screen', renderOpts: { screen: 'galleon' }, dials: [0, 1] });
        for (let l = 0; l < W.rows; l++) for (let d = 0; d < W.cols; d++) {
          widgetOwner.set(`${d},${l}`, s);
          s.targets.push({ id: `widget:${d},${l}`, type: 'lcd', piece: 'widget', dial: d, layer: l, rect: { x: d * W.w, y: l * W.h, w: W.w, h: W.h }, ...widgetArt(W) });
        }
      }
    }
    const widgets = Array.isArray(spec.widgets) ? spec.widgets.map((e, i) => [`${i % 2},${Math.floor(i / 2)}`, e]) : Object.entries(spec.widgets || {});
    for (const [at, raw] of widgets) {
      const e = entryOf(raw);
      if (!e) continue;
      const [d, l] = String(at).split(',').map(Number);
      if (!(d >= 0 && d < W.cols && l >= 0 && l < W.rows)) { problems.push(`widgets["${at}"]: use "dial,layer" with dial 0–1, layer 0–1`); continue; }
      if (widgetOwner.has(`${d},${l}`)) { problems.push(`widgets["${at}"]: already used by ${widgetOwner.get(`${d},${l}`).facet.id}`); continue; }
      const f = facetFor(e, `widgets["${at}"]`, (x) => (x.surface === 'screen' && x.screens.includes('galleon-widget') ? null : 'does not support a Galleon widget (galleon-widget)'));
      if (!f) continue;
      const s = slot(f, e, { kind: 'widget', renderOpts: { screen: 'galleon-widget' }, dials: [d], layer: l });
      widgetOwner.set(`${d},${l}`, s);
      s.targets.push({ id: `widget:${d},${l}`, type: 'lcd', piece: 'screen', dial: d, layer: l, rect: { x: d * W.w, y: l * W.h, w: W.w, h: W.h }, ...widgetArt(W) });
    }
  }

  return { slots, keyOwner, segOwner, widgetOwner, infobarOwner, problems, theme: spec.theme, mode: spec.mode };
}

