}

function putValue(out, t, runBits, v) {
  const a = v < 0 ? -v : v;
  let cat = 0;
  while ((1 << cat) <= a) cat++;
  const sym = runBits | cat;
  out.put(t.code[sym], t.size[sym]);
  if (cat) out.put(v < 0 ? (v - 1) & ((1 << cat) - 1) : v, cat);
