// D4's shared painting helpers for material themes (chrome, porcelain).
//
// A material stroke is a stack: a cast shadow or lower lip (offset down-right), a
// highlight or inner shadow (offset up-left), the body, and a specular core. Painting
// the stack per primitive would let one primitive's shadow cover the previous one's
// body, so `stack()` walks the glyph's pen tree once per LAYER — every shadow of the
// glyph, then every highlight, every body, every core — and merges runs of identical
// paint into a single <path>. Group transforms are kept; layer offsets are applied
// outside them, in grid units, so light always comes from the same corner.
//
//   stack(pen, (prim) => [{ layer: 3, a: strokeOf('#fff', 3) }, …], { layers: 5, offsets: { 1: [0.7, 0.9] } })

import { attrs, n } from '../scene/svg.js';
import { pathBounds } from '../scene/geom.js';

export function stack(pen, entriesOf, { layers, offsets = {} } = {}) {
  const memo = new Map();
  const entries = (p) => {
    let e = memo.get(p);
    if (!e) {
      e = (entriesOf(p) || []).filter(Boolean).map((x) => ({ ...x, d: x.d ?? p.d, key: keyOf(x.a) }));
      memo.set(p, e);
    }
    return e;
  };
  const walk = (node, L) => {
    let out = '', run = null;
    const flush = () => { if (run) { out += `<path${attrs({ d: run.d, ...run.a })}/>`; run = null; } };
    for (const c of node.children) {
      if (c.group) {
        flush();
        const inner = walk(c, L);
        if (inner) out += c.transform || c.opacity !== 1 ? `<g${attrs({ transform: c.transform, opacity: c.opacity !== 1 ? n(c.opacity, 3) : null })}>${inner}</g>` : inner;
        continue;
      }
      for (const e of entries(c)) {
        if (e.layer !== L) continue;
        if (run && run.key === e.key) run.d += e.d;
        else { flush(); run = { key: e.key, a: e.a, d: e.d }; }
      }
    }
    flush();
    return out;
  };
  let out = '';
  for (let L = 0; L < layers; L++) {
    const body = walk(pen.root, L);
    if (!body) continue;
    const off = offsets[L];
    out += off && (off[0] || off[1]) ? `<g transform="translate(${n(off[0], 3)} ${n(off[1], 3)})">${body}</g>` : body;
  }
  return out;
}

const keyOf = (a) => { let s = ''; for (const k in a) if (a[k] !== null && a[k] !== undefined) s += `${k}=${a[k]};`; return s; };

/** A one-primitive pen (for theme.paint(k, prim, style), the per-primitive entry point). */
export const onePen = (prim) => ({ root: { group: true, children: [prim] } });

/** Glyph lettering is the only pen geometry built from quadratic curves. */
export const isLettering = (prim) => prim.text === true || (prim.text === undefined && prim.fill === true && /Q/.test(prim.d));

const sideMemo = new Map();
/** Smallest side of a primitive's bounds in grid units (memoized: glyph geometry repeats every frame). */
export function minSide(prim) {
  let v = sideMemo.get(prim.d);
  if (v === undefined) {
    const b = pathBounds(prim.d);
    v = Math.min(b.w, b.h);
    if (sideMemo.size > 4000) sideMemo.clear();
    sideMemo.set(prim.d, v);
  }
  return v;
}

/** Stroke attributes (null-skipping, opacity only when < 1). */
export const strokeOf = (color, width, opacity = 1, { cap = 'round', join = 'round', dash = null } = {}) => ({
  fill: 'none', stroke: color, strokeWidth: n(width, 3), strokeOpacity: opacity < 0.999 ? n(Math.max(0, opacity), 3) : null,
  strokeLinecap: cap, strokeLinejoin: join, strokeDasharray: dash,
});
export const fillOf = (color, opacity = 1, extra = {}) => ({ fill: color, fillOpacity: opacity < 0.999 ? n(Math.max(0, opacity), 3) : null, ...extra });

/** Stroke options of a primitive under a role style. */
export const strokeOpts = (p, st) => ({ cap: p.cap || st.cap || 'round', join: p.join || st.join || 'round', dash: p.dash ? p.dash.map((v) => n(v)).join(' ') : null });

/** Per-surface memo: define a gradient (or anything) once per render surface. */
export function once(k, key, make) {
  const m = k._d4 || (k._d4 = new Map());
  if (!m.has(key)) m.set(key, make());
  return m.get(key);
}

/** Replace every fill color of text-outline markup (from defaultText) and wrap it in a translate — a cast copy for embossing. */
export function castText(markup, color, dx, dy, opacity) {
  const body = markup.replace(/ fill="#[0-9a-fA-F]{6}"/g, ` fill="${color}"`).replace(/ fill-opacity="[^"]*"/g, '');
  return `<g transform="translate(${n(dx)} ${n(dy)})"${opacity < 1 ? ` opacity="${n(opacity, 3)}"` : ''}>${body}</g>`;
}

sources.prism-deck/src/themes/_d5-print.js:
// Shared print-shop helpers for D5's themes (`paper`, `mono`): a layered glyph painter,
// halftone screens, paper fibers and a string hash for per-key (deterministic) texture.
//
//   layeredPaint(pen, (prim, i) => [{ layer, a }], { layers, offsets })   paint a glyph pass by pass
//   halftone({ x, y, w, h, pitch, from, color, opacity })                  a 45° dot screen, dots grow downward
//   fibers(seed, { x, y, w, h, count, len })                               short curved hairlines (cotton fibers)
//
// Everything is pure (no Date / Math.random): the same key always gets the same paper.

import { attrs, n } from '../scene/svg.js';
import { clamp } from '../scene/easing.js';
import { rng } from '../scene/noise.js';

/** FNV-1a over a string → uint32 (for per-key texture seeds from the render's idPrefix). */
export function strHash(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193); }
  return h >>> 0;
}

const keyOf = (a) => JSON.stringify(a);

/**
 * Paint a glyph pass by pass (every lip, then every ink body, then every core) instead of
 * primitive by primitive, so one primitive's under-layer never covers another's ink.
 * entriesOf(prim, i) → [{ layer, a: attrs-without-d, d? }]. Runs of identical paint merge
 * into one <path>. offsets: { [layer]: [dx, dy] } in grid units (registration, impression lips).
 */
export function layeredPaint(pen, entriesOf, { layers, offsets = {} } = {}) {
  const cache = new Map();
  let idx = 0;
  const entries = (p) => {
    let e = cache.get(p);
    if (!e) {
      e = (entriesOf(p, idx++) || []).filter(Boolean).map((x) => ({ ...x, d: x.d ?? p.d, key: keyOf(x.a) }));
      cache.set(p, e);
    }
    return e;
  };
  const walk = (node, L) => {
    let out = '', run = null;
    const flush = () => { if (run) { out += `<path${attrs({ d: run.d, ...run.a })}/>`; run = null; } };
    for (const c of node.children) {
      if (c.group) {
        flush();
        const inner = walk(c, L);
        if (!inner) continue;
        out += c.transform || c.opacity !== 1 ? `<g${attrs({ transform: c.transform, opacity: c.opacity !== 1 ? n(c.opacity, 3) : null })}>${inner}</g>` : inner;
        continue;
      }
      for (const e of entries(c)) {
        if (e.layer !== L) continue;
        if (run && run.key === e.key) run.d += e.d;
        else { flush(); run = { key: e.key, a: e.a, d: e.d }; }
      }
    }
    flush();
    return out;
  };
  let out = '';
  for (let L = 0; L < layers; L++) {
    const body = walk(pen.root, L);
    if (!body) continue;
    const off = offsets[L];
    out += off && (off[0] || off[1]) ? `<g transform="translate(${n(off[0])} ${n(off[1])})">${body}</g>` : body;
  }
  return out;
}

/** Stroke / fill attribute helpers for layeredPaint entries. */
export const strokeA = (color, width, opacity = 1, { cap = 'round', join = 'round', dash = null } = {}) => ({
  fill: 'none', stroke: color, strokeWidth: n(width), strokeOpacity: opacity < 0.999 ? n(clamp(opacity), 3) : null,
  strokeLinecap: cap, strokeLinejoin: join, strokeDasharray: dash,
});
export const fillA = (color, opacity = 1) => ({ fill: color, fillOpacity: opacity < 0.999 ? n(clamp(opacity), 3) : null });

/**
 * A halftone screen: dots on a 45° grid (`pitch` px between columns, rows at half pitch,
 * alternate rows offset), radius 0 at `from` (fraction of h from the top) growing to
 * `maxR` × pitch at the bottom edge. Each row is ONE dashed line (near-zero dashes with
 * round caps = dots), so a screen costs ~70 bytes a row whatever its width.
 */
export function halftone({ x = 0, y = 0, w, h, pitch, from = 0.5, maxR = 0.32, gamma = 1.25, color, opacity = 1 }) {
  let rows = '';
  const row = pitch / 2, top = y + h * from, span = h * (1 - from);
  for (let j = 0; ; j++) {
    const cy = y + h - row * (j + 0.35);
    if (cy < top) break;
    const r = maxR * pitch * Math.pow(clamp((cy - top) / span), gamma);
    if (r < 0.3) continue;
    const x0 = x + (j % 2) * pitch / 2 + pitch / 4, x1 = x + w - pitch * 0.1;
    if (x1 > x0) rows += `<path d="M${n(x0, 1)} ${n(cy, 1)}H${n(x1, 1)}" stroke-width="${n(2 * r, 2)}"/>`;
  }
  return rows ? `<g${attrs({ fill: 'none', stroke: color, strokeOpacity: opacity < 0.999 ? n(clamp(opacity), 3) : null, strokeLinecap: 'round', strokeDasharray: `0.01 ${n(pitch - 0.01, 2)}` })}>${rows}</g>` : '';
}

/** Cotton fibers: `count` short curved hairlines + a few flecks, seeded. → { fibers: d, flecks: d } */
export function fibers(seed, { x = 0, y = 0, w, h, count = 12, len = 8, fleck = 1 }) {
  const r = rng(seed);
  let d = '', f = '';
  for (let i = 0; i < count; i++) {
    const x0 = x + r() * w, y0 = y + r() * h, a = r() * Math.PI, L = len * (0.45 + r() * 0.8);
    const dx = Math.cos(a) * L, dy = Math.sin(a) * L, bend = (r() - 0.5) * L * 0.7;
    d += `M${n(x0, 1)} ${n(y0, 1)}q${n(dx / 2 - dy * bend / L, 1)} ${n(dy / 2 + dx * bend / L, 1)} ${n(dx, 1)} ${n(dy, 1)}`;
  }
  const flecks = Math.round(count / 3);
  for (let i = 0; i < flecks; i++) {
    const cx = x + r() * w, cy = y + r() * h, rr = fleck * (0.4 + r() * 0.6);
    f += `M${n(cx - rr, 1)} ${n(cy, 1)}a${n(rr, 2)} ${n(rr, 2)} 0 1 0 ${n(2 * rr, 2)} 0a${n(rr, 2)} ${n(rr, 2)} 0 1 0 ${n(-2 * rr, 2)} 0`;
  }
  return { fibers: d, flecks: f };
}

